files.text:
swimlane-beta LR
Image@{ img: "https://example.invalid/image.svg", label: Photo }
Icon@{ icon: "fa:home" }
Explicit@{ shape: rect, img: "https://example.invalid/image.svg", label: Explicit }
Again@{ icon: "fa:home", label: Earlier }
Again@{ shape: diamond, label: Later }
Falsy@{ shape: rect, img: false, icon: null, label: Vector }
Truthy@{ img: "false", label: String }
Image --> Icon

swimlane-beta
A@{
shape: rect
label: Empty metadata
metadata: !!map
}

swimlane-beta BT
subgraph outer ["Outer"]
subgraph "Anonymous nested work"
A@{ shape: rect, label: "<b>safe</b>" }
B@{ shape: diamond, label: "**Markdown**", labelType: markdown }
C@{ shape: circle, label: "Plain", labelType: string }
end
end
A -->|handoff| B
B --> C

swimlane-beta
Nan@{ shape: rect, label: .nan, img: .nan, icon: .nan, custom: .nan }
Inf@{ shape: rect, label: .inf, custom: .inf }
Negative@{ shape: rect, label: -.inf, custom: -.inf }
Overflow@{ shape: rect, label: 1e9999, custom: 1e9999 }
Binary@{ shape: rect, label: 0b101, custom: -0b11 }
Nan --> Inf --> Negative --> Overflow

